package mz.gov.mogovolas.expedientes.security;
import mz.gov.mogovolas.expedientes.entity.*; import mz.gov.mogovolas.expedientes.repository.UtilizadorRepository; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CustomUserDetailsService implements UserDetailsService { private final UtilizadorRepository repo; public CustomUserDetailsService(UtilizadorRepository r){repo=r;} public UserDetails loadUserByUsername(String n){ Utilizador u=repo.findByUsername(n).orElseThrow(()->new UsernameNotFoundException("Utilizador não encontrado")); Set<SimpleGrantedAuthority>a=new HashSet<>(); for(Papel p:u.getPapeis()){a.add(new SimpleGrantedAuthority("ROLE_"+p.getNome())); for(Permissao x:p.getPermissoes())a.add(new SimpleGrantedAuthority(x.getCodigo()));} return User.withUsername(u.getUsername()).password(u.getPassword()).authorities(a).disabled(!u.isActivo()||u.isBloqueado()).build(); } }
